"use client";

import * as React from "react";
import { ContextMenu as ContextMenuPrimitive } from "@base-ui/react/context-menu";

import { cn } from "@/lib/utils";
import { menuItemBase, popoverSurface, popupMotion } from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

type PositionerProps = Pick<ContextMenuPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset">;

/** The menu panel: the white floating panel, at least 12rem wide, padded 0.25rem. */
const menuPanel = cn(popoverSurface, popupMotion, "min-w-48 max-h-(--available-height) overflow-y-auto p-1");

/** Margin ContextMenu root: the actions a right click or long press offers. */
const ContextMenu = ContextMenuPrimitive.Root;

/** The area that opens the menu on right click or long press. */
const ContextMenuTrigger = ContextMenuPrimitive.Trigger;

/** Groups related rows and gives a label something to name. */
const ContextMenuGroup = ContextMenuPrimitive.Group;

/** Moves a menu panel to the end of the document body. */
const ContextMenuPortal = ContextMenuPrimitive.Portal;

/** Wraps a nested menu: its sub-trigger and its sub-content. */
const ContextMenuSub = ContextMenuPrimitive.SubmenuRoot;

/** Holds a set of radio rows where only one can be chosen. */
const ContextMenuRadioGroup = ContextMenuPrimitive.RadioGroup;

/** Margin context menu: the white floating panel, opened at the pointer and growing from that point. */
function ContextMenuContent({ className, ...props }: WithClassName<ContextMenuPrimitive.Popup.Props>) {
  return (
    <ContextMenuPrimitive.Portal>
      <ContextMenuPrimitive.Positioner className="isolate z-50 outline-none">
        <ContextMenuPrimitive.Popup data-slot="context-menu-content" className={cn(menuPanel, className)} {...props} />
      </ContextMenuPrimitive.Positioner>
    </ContextMenuPrimitive.Portal>
  );
}
ContextMenuContent.displayName = "ContextMenuContent";

/** A nested menu panel that opens beside its row, level with the row's top. */
function ContextMenuSubContent({
  className,
  align = "start",
  alignOffset = -4,
  side = "right",
  sideOffset = 4,
  ...props
}: WithClassName<ContextMenuPrimitive.Popup.Props> & PositionerProps) {
  return (
    <ContextMenuPrimitive.Portal>
      <ContextMenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <ContextMenuPrimitive.Popup data-slot="context-menu-sub-content" className={cn(menuPanel, className)} {...props} />
      </ContextMenuPrimitive.Positioner>
    </ContextMenuPrimitive.Portal>
  );
}
ContextMenuSubContent.displayName = "ContextMenuSubContent";

/**
 * A menu row, 2rem tall, that turns field grey under the pointer or keyboard.
 * The destructive variant turns the text red with a faint red wash.
 */
function ContextMenuItem({
  className,
  inset,
  variant = "default",
  ...props
}: WithClassName<ContextMenuPrimitive.Item.Props> & {
  inset?: boolean;
  variant?: "default" | "destructive";
}) {
  return (
    <ContextMenuPrimitive.Item
      data-slot="context-menu-item"
      data-variant={variant}
      className={cn(
        menuItemBase,
        variant === "destructive" &&
          "text-destructive-text data-[highlighted]:bg-destructive/10 data-[highlighted]:text-destructive-text [&_svg]:text-current",
        inset && "ps-8",
        className,
      )}
      {...props}
    />
  );
}
ContextMenuItem.displayName = "ContextMenuItem";

/** A row that opens a nested menu, with a caret at the end. */
function ContextMenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: WithClassName<ContextMenuPrimitive.SubmenuTrigger.Props> & { inset?: boolean }) {
  return (
    <ContextMenuPrimitive.SubmenuTrigger
      data-slot="context-menu-sub-trigger"
      className={cn(
        menuItemBase,
        "data-[popup-open]:bg-(--field) data-[popup-open]:text-accent-foreground",
        inset && "ps-8",
        className,
      )}
      {...props}
    >
      {children}
      <ChevronRightIcon className="ms-auto rtl:rotate-180" aria-hidden="true" />
    </ContextMenuPrimitive.SubmenuTrigger>
  );
}
ContextMenuSubTrigger.displayName = "ContextMenuSubTrigger";

/** A row that toggles on and off, with an oxblood tick at the start when on. */
function ContextMenuCheckboxItem({
  className,
  children,
  ...props
}: WithClassName<ContextMenuPrimitive.CheckboxItem.Props>) {
  return (
    <ContextMenuPrimitive.CheckboxItem
      data-slot="context-menu-checkbox-item"
      className={cn(menuItemBase, "ps-8", className)}
      {...props}
    >
      <span className="pointer-events-none absolute start-2 flex size-4 items-center justify-center">
        <ContextMenuPrimitive.CheckboxItemIndicator>
          <CheckIcon className="text-(--primary-text)!" aria-hidden="true" />
        </ContextMenuPrimitive.CheckboxItemIndicator>
      </span>
      {children}
    </ContextMenuPrimitive.CheckboxItem>
  );
}
ContextMenuCheckboxItem.displayName = "ContextMenuCheckboxItem";

/** One choice in a radio group, with a small oxblood dot at the start when chosen. */
function ContextMenuRadioItem({
  className,
  children,
  ...props
}: WithClassName<ContextMenuPrimitive.RadioItem.Props>) {
  return (
    <ContextMenuPrimitive.RadioItem
      data-slot="context-menu-radio-item"
      className={cn(menuItemBase, "ps-8", className)}
      {...props}
    >
      <span className="pointer-events-none absolute start-2 flex size-4 items-center justify-center">
        <ContextMenuPrimitive.RadioItemIndicator>
          <span className="block size-1.5 rounded-full bg-primary" />
        </ContextMenuPrimitive.RadioItemIndicator>
      </span>
      {children}
    </ContextMenuPrimitive.RadioItem>
  );
}
ContextMenuRadioItem.displayName = "ContextMenuRadioItem";

/** A small muted heading over a group of rows, used inside a group. */
function ContextMenuLabel({
  className,
  inset,
  ...props
}: WithClassName<ContextMenuPrimitive.GroupLabel.Props> & { inset?: boolean }) {
  return (
    <ContextMenuPrimitive.GroupLabel
      data-slot="context-menu-label"
      className={cn("px-2.5 py-1.5 text-xs font-medium text-muted-foreground", inset && "ps-8", className)}
      {...props}
    />
  );
}
ContextMenuLabel.displayName = "ContextMenuLabel";

/** A hairline between groups that runs to the panel's edges. */
function ContextMenuSeparator({ className, ...props }: WithClassName<ContextMenuPrimitive.Separator.Props>) {
  return (
    <ContextMenuPrimitive.Separator
      data-slot="context-menu-separator"
      className={cn("-mx-1 my-1 h-px bg-border", className)}
      {...props}
    />
  );
}
ContextMenuSeparator.displayName = "ContextMenuSeparator";

/** The keyboard shortcut at the end of a row, in small muted type. */
function ContextMenuShortcut({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      data-slot="context-menu-shortcut"
      className={cn("ms-auto ps-4 text-xs text-muted-foreground", className)}
      {...props}
    />
  );
}
ContextMenuShortcut.displayName = "ContextMenuShortcut";

export {
  ContextMenu,
  ContextMenuTrigger,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuCheckboxItem,
  ContextMenuRadioItem,
  ContextMenuLabel,
  ContextMenuSeparator,
  ContextMenuShortcut,
  ContextMenuGroup,
  ContextMenuPortal,
  ContextMenuSub,
  ContextMenuSubContent,
  ContextMenuSubTrigger,
  ContextMenuRadioGroup,
};

// Solar, the icon library this system pairs with, drawn inline
// so the installed component loads no icon at runtime:
// "solar:unread-linear" "solar:alt-arrow-right-linear"
// [BD-1029]
function CheckIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true" {...props}>
      <path fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M7 12.9L10.1429 16.5L18 7.5"/>
    </svg>
  );
}
function ChevronRightIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 24 24" aria-hidden="true" {...props}>
      <path fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M9 5L15 12L9 19"/>
    </svg>
  );
}
